'use client';
import { useEffect, useRef, useState, type CSSProperties, type RefObject } from 'react';
import { Brand, type BrandName } from '../lib/brands';
import { cx } from '../lib/cx';
import { useControllable, useIsoLayoutEffect, useReducedMotion } from '../lib/hooks';
import { Icon, type IconName } from '../lib/icons';
import { avatarInk, enter, Spin, Swap, Tip, useGrow } from '../lib/motion';
import { usePopover } from '../lib/popover';
import '../designme.css';
// its menus' rows glide in Clean
import '../lib/glide';
import './tool-connections.css';

/** off: the agent cannot use it, ask: it asks first, allow: it uses it freely */
export type ToolConnectionsPermission = 'off' | 'ask' | 'allow';

/** ok, testing while a check runs, error when it failed (the row offers Reconnect), reconnecting while that runs */
export type ToolConnectionsStatus = 'ok' | 'testing' | 'error' | 'reconnecting';

/** A tool or connection the agent can reach */
export interface ToolConnectionsTool {
  key: string;
  /** Like "Figma" */
  name: string;
  /** The quiet line under it, like "Read and edit frames" */
  detail?: string;
  /** A service's own logo, on a white tile. Wins over `icon` */
  brand?: BrandName;
  /** An icon on a vivid tile of `color`, for tools without a logo */
  icon?: IconName;
  /** The tile's colour, like 'var(--dm-av-t)'. The icon on it is white, or the colour's own ink for an avatar colour */
  color?: string;
  /** Defaults to ask */
  permission?: ToolConnectionsPermission;
  status?: ToolConnectionsStatus;
  /** Shown instead of the detail while it is set, like "Token expired. Reconnect to use it" */
  note?: string;
}

export interface ToolConnectionsProps {
  /** The connected tools. Leave it out to let the permission switches and Connect a tool change them */
  tools?: ToolConnectionsTool[];
  defaultTools?: ToolConnectionsTool[];
  onToolsChange?: (tools: ToolConnectionsTool[]) => void;
  /** Tools that can be connected, listed under Connect a tool. Ones already connected are left out */
  available?: ToolConnectionsTool[];
  /** Called with a tool picked from Connect a tool. It joins the list with "Just connected" and Ask */
  onConnect?: (tool: ToolConnectionsTool) => void;
  /** Adds a Test all button. Report progress through each tool's status and note */
  onTest?: () => void;
  /** A test is running: Test all shows a spinner and waits, and the test's line shimmers */
  testing?: boolean;
  /** Called by the Reconnect button of a tool whose status is error */
  onReconnect?: (key: string) => void;
  title?: string;
  /** A test's line, in the foot beside Connect a tool, like "4 of 4 healthy". It shimmers while `testing` is set. Left out,
      there is none: the rows already say what is connected */
  status?: string;
  /** Leads the test's line with the green tick, as after a test that found every tool healthy */
  healthy?: boolean;
  className?: string;
}

const PERMS: { value: ToolConnectionsPermission; label: string; tip: string }[] = [
  { value: 'off', label: 'Off', tip: 'Agent cannot use it' },
  { value: 'ask', label: 'Ask', tip: 'Agent asks first' },
  { value: 'allow', label: 'Allow', tip: 'Agent uses it freely' }
];

/** A button that is as wide as its words and eases to its new width when they change, as on designme.dev */
function useEaseWidth(ref: RefObject<HTMLElement | null>, words: unknown) {
  const reduce = useReducedMotion(), was = useRef(0);
  useIsoLayoutEffect(() => {
    const b = ref.current; if (!b) return;
    const w1 = b.getBoundingClientRect().width, w0 = was.current; was.current = w1;
    const cs = getComputedStyle(b), t = cs.getPropertyValue('--dm-t').trim();
    if (w0 && !reduce && Math.abs(w1 - w0) > .5) b.animate([{ width: w0 + 'px' }, { width: w1 + 'px' }], { duration: (t.endsWith('ms') ? parseFloat(t) : parseFloat(t) * 1000) || 340, easing: cs.getPropertyValue('--dm-ease').trim() || 'ease' });
  }, [words]);
}

/** The three-way permission switch, with a knob that slides to the pick */
function Permission({ name, value, onChange }: { name: string; value: ToolConnectionsPermission; onChange: (p: ToolConnectionsPermission) => void }) {
  const ref = useRef<HTMLDivElement>(null);
  const [knob, setKnob] = useState<CSSProperties>({});
  // the knob slides when the choice changes; when the row first appears it is simply in place
  const placed = useRef(false);
  useIsoLayoutEffect(() => {
    const el = ref.current; if (!el) return;
    const place = () => { const b = el.querySelector<HTMLElement>('[aria-pressed="true"]'); if (b){ setKnob({ left: b.offsetLeft, width: b.offsetWidth, transition: placed.current ? undefined : 'none' }); placed.current = true; } };
    place();
    const ro = new ResizeObserver(place); ro.observe(el);
    return () => ro.disconnect();
  }, [value]);
  return (
    <div className="dm-hnx-pm" role="group" aria-label={name + ' permission'} ref={ref}>
      <span className="dm-kn" style={knob} />
      {PERMS.map(p => <Tip key={p.value} label={p.tip}><button type="button" aria-pressed={p.value === value} onClick={() => onChange(p.value)} onMouseDown={e => e.preventDefault()}>{p.label}</button></Tip>)}
    </div>
  );
}

/** The logo on a white tile, or the icon on a vivid tile of its colour */
const Mark = ({ tool }: { tool: ToolConnectionsTool }) => tool.brand
  ? <span className="dm-ic dm-brandic" aria-hidden="true"><Brand name={tool.brand} /></span>
  : <span className="dm-ic" style={{ background: tool.color ?? 'var(--dm-av-b)', color: avatarInk(tool.color ?? 'var(--dm-av-b)') ?? '#fff' }} aria-hidden="true">{tool.icon && <Icon name={tool.icon} size="xs" />}</span>;

/** Reconnect, as wide as its words; while it reconnects it keeps its width and spins */
function Reconnect({ busy, onClick }: { busy: boolean; onClick: () => void }) {
  // its width with its word, kept while the spinner takes the word's place; it keeps its colour and takes no second press
  const ref = useRef<HTMLButtonElement>(null), w = useRef<number>(0);
  useIsoLayoutEffect(() => { if (!busy && ref.current) w.current = ref.current.getBoundingClientRect().width; });
  return <button ref={ref} type="button" className="dm-pill dm-accent dm-sm dm-enter" style={busy && w.current ? { width: w.current } : undefined} aria-disabled={busy || undefined} aria-label={busy ? 'Reconnecting' : undefined} onClick={() => !busy && onClick()}>{busy ? <Spin /> : 'Reconnect'}</button>;
}

/** The tools the agent can reach, and how much it may do with each. */
export function ToolConnections({ tools, defaultTools = [], onToolsChange, available = [], onConnect, onTest, testing = false, onReconnect, title = 'Tools and connections', status, healthy = false, className }: ToolConnectionsProps) {
  const [list, setList] = useControllable(tools, defaultTools, onToolsChange);
  // a menu opens under its button, or above it when there is no room
  const menu = usePopover();
  const [root, inner] = useGrow();
  const test = useRef<HTMLButtonElement>(null);
  useEaseWidth(test, testing);
  const perm = (t: ToolConnectionsTool) => t.permission ?? 'ask';
  const left = available.filter(a => !list.some(t => t.key === a.key));

  // rows there from the start come in one after another; a row connected later, or back from Reconnect, comes in on its own
  const [first] = useState(() => list.map(t => t.key));
  const [epoch, setEpoch] = useState<Record<string, number>>({});
  const was = useRef<Record<string, ToolConnectionsStatus | undefined>>({});
  useEffect(() => {
    const back = list.filter(t => was.current[t.key] === 'reconnecting' && t.status !== 'reconnecting' && t.status !== 'error').map(t => t.key);
    if (back.length) setEpoch(e => ({ ...e, ...Object.fromEntries(back.map(k => [k, (e[k] ?? 0) + 1])) }));
    was.current = Object.fromEntries(list.map(t => [t.key, t.status]));
  }, [list]);

  const change = (key: string, p: ToolConnectionsPermission) => setList(list.map(t => t.key === key ? { ...t, permission: p } : t));
  const connect = (tool: ToolConnectionsTool) => {
    menu.closeSoon();
    setList([...list, { ...tool, detail: 'Just connected', permission: 'ask' }]);
    onConnect?.(tool);
  };

  return (
    <div data-dm="" ref={root} className={cx('dm-hnx dm-panel dm-growing', className)}>
      <div ref={inner} className="dm-grow">
        <div className="dm-hnx-h">
          <span className="dm-hnx-hi" aria-hidden="true"><Icon name="link" size="xs" /></span>
          <div className="dm-hnx-ht"><b>{title}</b></div>
          {onTest && <button ref={test} type="button" className="dm-pill dm-ghost dm-sm dm-hnx-test" onClick={onTest} disabled={testing}>{testing ? <><Spin /><span>Testing</span></> : <><Icon name="refresh" size="xs" /><span>Test all</span></>}</button>}
        </div>
        <div className="dm-hnx-list" role="list" aria-label="Tools">
          {list.map(t => {
            const at = first.indexOf(t.key), again = epoch[t.key] ?? 0;
            const motion = at >= 0 && !again ? enter(at * 50) : enter(0);
            const err = t.status === 'error' || t.status === 'reconnecting';
            return (
              <div key={t.key + ':' + again} role="listitem" className={cx('dm-hnx-t', motion.className, perm(t) === 'off' && 'dm-off', t.status === 'testing' && 'dm-chk', err && 'dm-err')} style={motion.style}>
                <Mark tool={t} />
                <span className="dm-t"><span className="dm-nm"><span>{t.name}</span><i className="dm-hnx-dot" aria-hidden="true" /></span><Swap className="dm-d">{t.note ?? t.detail ?? ''}</Swap></span>
                {err
                  ? <Reconnect busy={t.status === 'reconnecting'} onClick={() => t.status === 'error' && onReconnect?.(t.key)} />
                  : <Permission name={t.name} value={perm(t)} onChange={p => change(t.key, p)} />}
              </div>
            );
          })}
        </div>
        <div className="dm-hnx-ft">
          <button type="button" className="dm-hnx-add" {...menu.trigger}><Icon name="plus" size="xs" />Connect a tool</button>
          {/* a test's progress and result, beside Connect a tool */}
          <span className="dm-muted dm-hnx-st" aria-live="polite">{status && <>{healthy && !testing && <Icon name="ok" size="xs" />}<Swap className={testing ? 'dm-shim' : undefined}>{status}</Swap></>}</span>
        </div>
        <div {...menu.pop} className={cx(menu.pop.className, 'dm-hnx-pop')} role="menu" aria-label="Connect a tool">
          {left.length
            ? left.map(a => <button type="button" key={a.key} className="dm-mi" role="menuitem" onClick={() => connect(a)}>{a.brand ? <Brand name={a.brand} /> : a.icon && <Icon name={a.icon} size="xs" />}<span>{a.name}</span></button>)
            : <div className="dm-ph">All tools connected</div>}
        </div>
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Tools and connections ---------- */
/* the tools the agent can reach, each with an Off, Ask or Allow switch. The card sits on two columns (owner, 18 Nov), its
   content 16px from every edge: the head's neutral mark in a 28px column with each tool's mark under it, and the title and
   each tool's words 12px after it; the switches, Reconnect and Test all's words end on the content's right edge, and each
   row shares one centre line. A row is not a button, so it has no hover fill. A tool's state is a small dot after its name,
   beside it and never over its mark: green while it is connected, red once it has failed, a turning ring while it is tested
   (the -mark colours, 3:1), none while it is off, when the row dims. Its mark is the tool's logo on a white tile, or its icon
   on a vivid tile of its colour (white or the colour's own ink on it). A test's progress and result are a line in the foot,
   beside Connect a tool. The card grows and shrinks with its rows (grow()) */
.dm-hnx{padding:var(--dm-s-4);display:flex;flex-direction:column}
.dm-hnx.dm-growing:has(.dm-pop.dm-open){overflow:visible}
.dm-hnx-h{display:flex;align-items:center;gap:var(--dm-s-3);padding-bottom:var(--dm-s-2)}
.dm-hnx-hi{width:28px;height:28px;display:grid;place-items:center;flex:none;border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));color:var(--dm-fg2);background:var(--dm-chip)}
.dm-hnx-ht{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-hnx-h b{font-weight:500;font-size:14px;line-height:20px}
/* a test's progress and result sit in the foot, beside Connect a tool, its words ending on the content's right edge */
/* the foot sits under a hairline in Soft and Blueprint (owner, 21 Nov: "blueprint should have divider lines at the bottom"),
   8px under the last tool and 8px over its button, as the rows are spaced; Clean's is a foot strip (below) */
.dm-hnx-ft{display:flex;align-items:center;gap:var(--dm-s-3);margin-top:0;padding-top:var(--dm-s-2);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-hnx-st{display:flex;align-items:center;gap:5px;min-width:0;margin-left:auto;height:18px;font-size:12px;line-height:18px;white-space:nowrap}
.dm-hnx-st>span{min-width:0;overflow:hidden;text-overflow:ellipsis}
.dm-hnx-st .dm-i{flex:none;color:var(--dm-ok-mark)}
.dm-hnx-st .dm-shim{font-size:inherit}
.dm-hnx-st:empty{display:none}
/* Test all: its words end on the content's right edge and its hover box reaches out round them; it is as wide as its words,
   and eases to its new width when they change */
.dm-hnx-test{flex:none;margin-right:-11px;overflow:hidden}
.dm-hnx-test .dm-spin{width:11px;height:11px}
.dm-hnx-list{display:flex;flex-direction:column}
.dm-hnx-t{display:grid;grid-template-columns:28px minmax(0,1fr) auto;align-items:center;column-gap:var(--dm-s-3);padding:var(--dm-s-2) 0;font-size:13px}
.dm-hnx-t .dm-ic{width:28px;height:28px;border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));display:grid;place-items:center;transition:opacity var(--dm-t-fast) var(--dm-ease)}
.dm-hnx-t .dm-ic.dm-brandic{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);color:var(--dm-fg)}
.dm-hnx-t .dm-ic .dm-brand{width:15px;height:15px}
.dm-hnx-t .dm-t{min-width:0;display:flex;flex-direction:column}
.dm-hnx-t .dm-nm{display:flex;align-items:center;gap:6px;min-width:0;line-height:20px;transition:color var(--dm-t-fast) var(--dm-ease)}
.dm-hnx-t .dm-nm>span:first-child{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-hnx-t .dm-d{font-size:12px;line-height:18px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-hnx-t.dm-err .dm-d{color:var(--dm-bad);white-space:normal;text-wrap:pretty}
/* the state: a dot after the name (connected, failed), a turning ring while it is tested */
.dm-hnx-dot{flex:none;width:6px;height:6px;border-radius:50%;background:var(--dm-ok-mark);transition:background-color var(--dm-t-fast) var(--dm-ease),opacity var(--dm-t-fast) var(--dm-ease)}
.dm-hnx-t.dm-err .dm-hnx-dot{background:var(--dm-bad-mark)}
.dm-hnx-t.dm-off .dm-hnx-dot{opacity:0}
.dm-hnx-t.dm-chk .dm-hnx-dot{width:10px;height:10px;box-sizing:border-box;background:none;border:1.5px solid var(--dm-accent-mark,var(--dm-accent));border-right-color:transparent;opacity:1;animation:dm-rot .8s linear infinite;transition:none}
/* the turning ring stays round in Blueprint, as its other loaders do */
:root:not([data-style="soft"],[data-style="clean"]) .dm-hnx-t.dm-chk .dm-hnx-dot:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){border-radius:50%!important}
/* off: the mark fades and the name steps down to muted, so the text stays readable */
.dm-hnx-t.dm-off .dm-ic{opacity:.5}
.dm-hnx-t.dm-off .dm-nm{color:var(--dm-muted)}
/* the same pill switch as every other segmented switch */
.dm-hnx-pm{display:grid;grid-template-columns:repeat(3,auto);padding:2px;border-radius:var(--dm-r-pill);background:var(--dm-chip);position:relative}
.dm-hnx-pm button{position:relative;z-index:1;height:24px;padding:0 9px;border-radius:var(--dm-r-pill);font-size:11.5px;color:var(--dm-muted);transition:color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.dm-hnx-pm button:hover{color:var(--dm-fg2)}}
.dm-hnx-pm button[aria-pressed="true"]{color:var(--dm-fg)}
.dm-hnx-pm button:focus-visible{outline-offset:-2px}
.dm-hnx-pm .dm-kn{position:absolute;top:2px;bottom:2px;border-radius:var(--dm-r-pill);background:var(--dm-surface);box-shadow:0 1px 2px rgba(0,0,0,.08);transition:left var(--dm-t) var(--dm-ease),width var(--dm-t) var(--dm-ease)}
.dm-hnx-t .dm-pill .dm-spin{width:11px;height:11px}
/* Connect a tool: its + centred in the marks' column and its words on the title's; the hover box starts on the content's edge */
.dm-hnx-add{display:flex;align-items:center;gap:var(--dm-s-3);flex:none;height:32px;padding:0 var(--dm-s-3) 0 0;font-size:13px;color:var(--dm-fg2);border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
.dm-hnx-add>.dm-i{width:28px;padding:0 8px;box-sizing:border-box}
.dm-hnx-add[aria-expanded="true"]{color:var(--dm-fg);background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.dm-hnx-add:hover{color:var(--dm-fg);background:var(--dm-row)}}
.dm-hnx-pop{min-width:220px}
.dm-hnx-pop .dm-mi .dm-brand{width:12px;height:12px}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink primary alone presses */
.dm-hnx :is(.dm-ib,.dm-pill):active,:root[data-style="clean"] .dm-hnx .dm-ib:active,:root [data-style="clean"] .dm-hnx .dm-ib:active,:root [data-style="clean"].dm-hnx .dm-ib:active{transform:none}
/* Clean (owner, 17 and 18 Nov): the head an off-white strip with a hairline under it, Test all a flat secondary button 8px
   from the strip's top and bottom and 16px from the card's right edge; the tools' marks one neutral grey with a hairline (their logos keep their own
   colours); Connect a tool a flat secondary button on an off-white foot strip, 8px from its top and bottom and 16px in from
   the sides like everything in the card (21 Nov); the content 16px in from each edge and 16px from each strip; the switch is Clean's, a white knob on a track with an inner shadow */
:root[data-style="clean"] .dm-hnx.dm-panel,:root [data-style="clean"] .dm-hnx.dm-panel,:root [data-style="clean"].dm-hnx.dm-panel{padding:0}
/* the strips' buttons sit on the content's columns (owner, 21 Nov: "why do the components on the left have all different
   alignment?", "same on the right"): Test all ends where the switches end, 16px in, and Connect a tool starts where the marks
   start, 16px in; the strips themselves keep their 8px above and below */
:root[data-style="clean"] .dm-hnx-h,:root [data-style="clean"] .dm-hnx-h,:root [data-style="clean"].dm-hnx-h{min-height:44px;padding:8px 16px 8px 16px;background:var(--dm-strip);border-bottom:1px solid var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0}
:root[data-style="clean"] .dm-hnx-hi,:root [data-style="clean"] .dm-hnx-hi,:root [data-style="clean"].dm-hnx-hi{background:var(--dm-surface);box-shadow:inset 0 0 0 1px var(--dm-hair);border-radius:10px}
