@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-pill.dm-hnx-test:hover,:root [data-style="clean"] .dm-pill.dm-hnx-test:hover,:root [data-style="clean"].dm-pill.dm-hnx-test:hover{background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .dm-pill.dm-hnx-test:active,:root [data-style="clean"] .dm-pill.dm-hnx-test:active,:root [data-style="clean"].dm-pill.dm-hnx-test:active{box-shadow:var(--dm-btn2-press)}
:root[data-style="clean"] .dm-pill.dm-hnx-test[disabled],:root [data-style="clean"] .dm-pill.dm-hnx-test[disabled],:root [data-style="clean"].dm-pill.dm-hnx-test[disabled]{color:var(--dm-muted);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-pill.dm-hnx-test[disabled]:hover,:root [data-style="clean"] .dm-pill.dm-hnx-test[disabled]:hover,:root [data-style="clean"].dm-pill.dm-hnx-test[disabled]:hover{color:var(--dm-muted);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}}
:root[data-style="clean"] .dm-hnx-st .dm-i,:root [data-style="clean"] .dm-hnx-st .dm-i,:root [data-style="clean"].dm-hnx-st .dm-i{color:color-mix(in srgb,var(--dm-ok-mark) 80%,var(--dm-ok))}
:root[data-style="clean"] .dm-hnx-list,:root [data-style="clean"] .dm-hnx-list,:root [data-style="clean"].dm-hnx-list{padding:var(--dm-s-2) var(--dm-s-4)}
:root[data-style="clean"] .dm-hnx-t .dm-ic,:root [data-style="clean"] .dm-hnx-t .dm-ic,:root [data-style="clean"].dm-hnx-t .dm-ic,:root[data-style="clean"] .dm-hnx-t .dm-ic.dm-brandic,:root [data-style="clean"] .dm-hnx-t .dm-ic.dm-brandic,:root [data-style="clean"].dm-hnx-t .dm-ic.dm-brandic{background:var(--dm-surface)!important;color:var(--dm-fg2)!important;box-shadow:inset 0 0 0 1px var(--dm-hair);border-radius:10px}
:root[data-style="clean"] .dm-hnx-pm,:root [data-style="clean"] .dm-hnx-pm,:root [data-style="clean"].dm-hnx-pm{background:var(--dm-chip);box-shadow:var(--dm-track-ring)}
:root[data-style="clean"] .dm-hnx-pm .dm-kn,:root [data-style="clean"] .dm-hnx-pm .dm-kn,:root [data-style="clean"].dm-hnx-pm .dm-kn{background:var(--dm-knob);box-shadow:var(--dm-knob-shadow);transition:left var(--dm-t) var(--dm-ease),width var(--dm-t) var(--dm-ease)}
